$pagina='Control de Cocina'; require_once __DIR__.'/layout.php';
?>
<div class="card"><div class="card-header"><h3>🍲 Consolidado diario de raciones</h3><div style="display:flex;gap:.5rem"><input type="date" id="fechaCocina" class="form-control" value="<?= date('Y-m-d') ?>"><button class="btn btn-primary" onclick="cargar()">Consultar</button></div></div><div class="card-body"><div id="resumenCocina" class="alert alert-info">Consulta las raciones del día.</div><div style="display:flex;gap:.5rem;flex-wrap:wrap;margin-bottom:1rem"><button class="btn btn-warning" onclick="corte()">Aplicar corte 09:00</button></div><div class="table-responsive"><table class="table"><thead><tr><th>Titular</th><th>Beneficiario</th><th>Modalidad</th><th>Tarifa</th><th>Estado</th><th>Acción</th></tr></thead><tbody id="filasCocina"></tbody></table></div></div></div>
<script>let filas=[];async function cargar(){const fecha=document.getElementById('fechaCocina').value;const r=await apiGet('/backend/api/cocina.php',{action:'consolidado',fecha});filas=r.data||[];document.getElementById('resumenCocina').textContent='Total de raciones confirmadas: '+(r.total_raciones||0);document.getElementById('filasCocina').innerHTML=filas.map(x=>`<tr><td>${esc(x.titular)}</td><td>${esc(x.tipo_beneficiario==='FAMILIAR'?x.familiar:x.titular)}</td><td>${x.modalidad}</td><td>Bs ${Number(x.tarifa).toFixed(2)}</td><td>${x.estado}</td><td>${x.estado!=='ENTREGADO'?`<button class="btn btn-success btn-sm" onclick="entregar(${x.id})">Marcar entregado</button>`:'Entregado'}</td></tr>`).join('')||'<tr><td colspan="6">Sin raciones registradas.</td></tr>'; }function esc(x){return String(x||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}async function entregar(id){const r=await apiPost('/backend/api/cocina.php',{action:'entregar',reserva_id:id,fecha:document.getElementById('fechaCocina').value});Toast[r.success?'success':'error'](r.message);cargar();}async function corte(){const r=await apiPost('/backend/api/cocina.php',{action:'cerrar_corte',fecha:document.getElementById('fechaCocina').value});Toast[r.success?'success':'error'](r.message);cargar();}cargar();</script>
